begin;
create table public.conversations(id uuid primary key default gen_random_uuid(),user_a uuid not null references auth.users(id) on delete cascade,user_b uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now(),check(user_a<user_b),unique(user_a,user_b));
create function private.conversation_access(c uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.conversations where id=c and auth.uid() in (user_a,user_b) and private.is_friend(case when user_a=auth.uid() then user_b else user_a end)) $$;
create table public.messages(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.conversations(id) on delete cascade,sender_id uuid not null references auth.users(id) on delete cascade,body text not null check(length(body) between 1 and 4000),created_at timestamptz not null default now());
create index on public.messages(conversation_id,created_at);
alter table public.conversations enable row level security;
create policy participants on public.conversations for select to authenticated using(private.conversation_access(id));
create policy start_conversation on public.conversations for insert to authenticated with check(auth.uid() in(user_a,user_b) and private.is_friend(case when user_a=auth.uid() then user_b else user_a end));
revoke all on public.conversations from anon,authenticated;grant select,insert on public.conversations to authenticated;
alter table public.messages enable row level security;
create policy participants on public.messages for select to authenticated using(private.conversation_access(conversation_id));
create policy send on public.messages for insert to authenticated with check(sender_id=auth.uid() and private.conversation_access(conversation_id));
create policy unsend on public.messages for delete to authenticated using(sender_id=auth.uid());
revoke all on public.messages from anon,authenticated;grant select,insert,delete on public.messages to authenticated;
create table public.notifications(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,actor_id uuid references auth.users(id) on delete cascade,kind text not null,resource_id uuid,created_at timestamptz not null default now(),read_at timestamptz);
create index on public.notifications(owner_id,created_at desc);
alter table public.notifications enable row level security;
create policy own_notifications on public.notifications for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
revoke all on public.notifications from anon,authenticated;grant select,delete on public.notifications to authenticated;grant update(read_at) on public.notifications to authenticated;
create table public.feed_posts(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,kind text not null check(kind in('workout','record','rank','cardio','achievement')),snapshot jsonb not null check(jsonb_typeof(snapshot)='object'),created_at timestamptz not null default now());
create index on public.feed_posts(created_at desc);
create function private.feed_access(p uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.feed_posts where id=p and (owner_id=auth.uid() or private.is_friend(owner_id))) $$;
alter table public.feed_posts enable row level security;
create policy friends_feed on public.feed_posts for select to authenticated using(owner_id=auth.uid() or private.is_friend(owner_id));
create policy delete_own_post on public.feed_posts for delete to authenticated using(owner_id=auth.uid());
revoke all on public.feed_posts from anon,authenticated;grant select,delete on public.feed_posts to authenticated;
create table public.reactions(post_id uuid not null references public.feed_posts(id) on delete cascade,actor_id uuid not null references auth.users(id) on delete cascade,reaction text not null check(reaction in('❤️','🔥','💪','👏','🏆','😂')),primary key(post_id,actor_id));
alter table public.reactions enable row level security;
create policy read_visible on public.reactions for select to authenticated using(private.feed_access(post_id));
create policy react on public.reactions for insert to authenticated with check(actor_id=auth.uid() and private.feed_access(post_id));
create policy remove on public.reactions for delete to authenticated using(actor_id=auth.uid());
revoke all on public.reactions from anon,authenticated;grant select,insert,delete on public.reactions to authenticated;
create table public.comments(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.feed_posts(id) on delete cascade,actor_id uuid not null references auth.users(id) on delete cascade,body text not null check(length(body) between 1 and 2000),created_at timestamptz not null default now());
create index on public.comments(post_id,created_at);
alter table public.comments enable row level security;
create policy read_visible on public.comments for select to authenticated using(private.feed_access(post_id));
create policy comment on public.comments for insert to authenticated with check(actor_id=auth.uid() and private.feed_access(post_id));
create policy remove on public.comments for delete to authenticated using(actor_id=auth.uid());
revoke all on public.comments from anon,authenticated;grant select,insert,delete on public.comments to authenticated;
create table public.workout_exchanges(id uuid primary key default gen_random_uuid(),sender_id uuid not null references auth.users(id) on delete cascade,recipient_id uuid not null references auth.users(id) on delete cascade,routine_snapshot jsonb not null,initial_message text not null default '' check(length(initial_message)<=2000),status text not null default 'pending' check(status in('pending','accepted','declined','returned')),created_at timestamptz not null default now(),check(sender_id<>recipient_id));
create index on public.workout_exchanges(recipient_id,created_at desc);
create function private.exchange_access(e uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.workout_exchanges where id=e and auth.uid() in(sender_id,recipient_id) and private.is_friend(case when sender_id=auth.uid() then recipient_id else sender_id end)) $$;
create table public.exchange_results(exchange_id uuid primary key references public.workout_exchanges(id) on delete cascade,owner_id uuid not null references auth.users(id) on delete cascade,workout_snapshot jsonb not null,returned_at timestamptz not null default now());
create table public.exchange_messages(id uuid primary key default gen_random_uuid(),exchange_id uuid not null references public.workout_exchanges(id) on delete cascade,sender_id uuid not null references auth.users(id) on delete cascade,body text not null check(length(body) between 1 and 4000),created_at timestamptz not null default now());
create table public.exchange_reactions(exchange_id uuid not null references public.workout_exchanges(id) on delete cascade,actor_id uuid not null references auth.users(id) on delete cascade,reaction text not null check(reaction in('❤️','🔥','💪','👏','🏆','😂')),primary key(exchange_id,actor_id));
create index on public.exchange_messages(exchange_id,created_at);
alter table public.workout_exchanges enable row level security;
create policy participants on public.workout_exchanges for select to authenticated using(private.exchange_access(id));
alter table public.exchange_results enable row level security;
create policy participants on public.exchange_results for select to authenticated using(private.exchange_access(exchange_id));
alter table public.exchange_messages enable row level security;
create policy participants on public.exchange_messages for select to authenticated using(private.exchange_access(exchange_id));
create policy send on public.exchange_messages for insert to authenticated with check(sender_id=auth.uid() and private.exchange_access(exchange_id));
alter table public.exchange_reactions enable row level security;
create policy participants on public.exchange_reactions for select to authenticated using(private.exchange_access(exchange_id));
create policy react on public.exchange_reactions for insert to authenticated with check(actor_id=auth.uid() and private.exchange_access(exchange_id));
create policy remove on public.exchange_reactions for delete to authenticated using(actor_id=auth.uid());
revoke all on public.workout_exchanges,public.exchange_results,public.exchange_messages,public.exchange_reactions from anon,authenticated;
grant select on public.workout_exchanges,public.exchange_results,public.exchange_messages,public.exchange_reactions to authenticated;
grant insert on public.exchange_messages,public.exchange_reactions to authenticated;grant delete on public.exchange_reactions to authenticated;
create function public.send_workout_exchange(routine_id uuid,target uuid,message text default '') returns uuid language plpgsql security definer set search_path='' as $$declare snapshot jsonb;result uuid;begin
 if not private.is_friend(target) then raise exception 'Accepted friendship required' using errcode='42501';end if;
 snapshot:=private.sync_payload(auth.uid(),'routine',routine_id::text);if snapshot is null then raise exception 'Owned routine not found';end if;
 insert into public.workout_exchanges(sender_id,recipient_id,routine_snapshot,initial_message) values(auth.uid(),target,snapshot,message) returning id into result;
 insert into public.notifications(owner_id,actor_id,kind,resource_id) values(target,auth.uid(),'exchange_invitation',result);return result;end $$;
create function public.respond_workout_exchange(exchange_id uuid,accept boolean) returns void language plpgsql security definer set search_path='' as $$begin
 if not private.exchange_access(exchange_id) then raise exception 'Exchange unavailable' using errcode='42501';end if;
 update public.workout_exchanges set status=case when accept then 'accepted' else 'declined' end where id=exchange_id and recipient_id=auth.uid() and status='pending';
 if not found then raise exception 'Only recipient can respond to pending exchange' using errcode='42501';end if;end $$;
create function public.return_exchange_results(exchange_id uuid,session_id uuid) returns void language plpgsql security definer set search_path='' as $$declare r public.workout_exchanges;snapshot jsonb;begin
 select * into r from public.workout_exchanges where id=exchange_id for update;
 if r.recipient_id is distinct from auth.uid() or r.status<>'accepted' or not private.exchange_access(exchange_id) then raise exception 'Exchange unavailable' using errcode='42501';end if;
 snapshot:=private.sync_payload(auth.uid(),'workout',session_id::text);if snapshot is null then raise exception 'Owned workout not found';end if;
 insert into public.exchange_results(exchange_id,owner_id,workout_snapshot) values(exchange_id,auth.uid(),snapshot);update public.workout_exchanges set status='returned' where id=exchange_id;
 insert into public.notifications(owner_id,actor_id,kind,resource_id) values(r.sender_id,auth.uid(),'exchange_results',exchange_id);end $$;
create function public.publish_workout(session_id uuid) returns uuid language plpgsql security definer set search_path='' as $$declare snapshot jsonb;result uuid;begin
 snapshot:=private.sync_payload(auth.uid(),'workout',session_id::text);if snapshot is null then raise exception 'Owned workout not found';end if;
 insert into public.feed_posts(owner_id,kind,snapshot) values(auth.uid(),'workout',snapshot) returning id into result;return result;end $$;
create function public.respond_relationship(request_id uuid,accept boolean) returns void language plpgsql security definer set search_path='' as $$begin
 update public.relationships set status=case when accept then 'accepted' else 'declined' end where id=request_id and recipient_id=auth.uid() and status='pending' and private.is_friend(requester_id);
 if not found then raise exception 'Relationship request unavailable' using errcode='42501';end if;end $$;
create table public.challenges(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,name text not null,metric text not null check(metric in('workouts','walking_distance','cardio_minutes')),starts_on date not null,ends_on date not null,goal numeric not null check(goal>0),check(ends_on>=starts_on));
create table public.challenge_members(challenge_id uuid not null references public.challenges(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,primary key(challenge_id,user_id));
create function private.challenge_access(c uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.challenges where id=c and(owner_id=auth.uid() or(private.is_friend(owner_id) and exists(select 1 from public.challenge_members where challenge_id=c and user_id=auth.uid())))) $$;
alter table public.challenges enable row level security;
create policy members on public.challenges for select to authenticated using(private.challenge_access(id));
create policy create_own on public.challenges for insert to authenticated with check(owner_id=auth.uid());
create policy remove_own on public.challenges for delete to authenticated using(owner_id=auth.uid());
alter table public.challenge_members enable row level security;
create policy members on public.challenge_members for select to authenticated using(private.challenge_access(challenge_id));
create policy opt_in on public.challenge_members for insert to authenticated with check(user_id=auth.uid() and exists(select 1 from public.challenges where id=challenge_id and (owner_id=auth.uid() or private.is_friend(owner_id))));
create policy opt_out on public.challenge_members for delete to authenticated using(user_id=auth.uid());
revoke all on public.challenges,public.challenge_members from anon,authenticated;grant select,insert,delete on public.challenges,public.challenge_members to authenticated;
-- Buckets are PRIVATE, including avatars. Read access uses signed/authenticated requests.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('avatars','avatars',false,5242880,array['image/jpeg','image/png','image/webp']),('progress-photos','progress-photos',false,10485760,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
create function private.photo_access(path text,category_name text) returns boolean language plpgsql stable security definer set search_path='' as $$declare owner uuid;begin
 if split_part(path,'/',1)!~'^[0-9a-fA-F-]{36}$' then return false;end if;
 begin owner:=split_part(path,'/',1)::uuid;exception when invalid_text_representation then return false;end;
 if category_name='avatar' then return private.not_blocked(owner);end if;return private.can_read(owner,'progress_photos');end $$;
create policy own_photo_upload on storage.objects for insert to authenticated with check(bucket_id in('avatars','progress-photos') and (storage.foldername(name))[1]=auth.uid()::text);
create policy own_photo_delete on storage.objects for delete to authenticated using(bucket_id in('avatars','progress-photos') and (storage.foldername(name))[1]=auth.uid()::text);
create policy allowed_photo_read on storage.objects for select to authenticated using((bucket_id='avatars' and private.photo_access(name,'avatar')) or(bucket_id='progress-photos' and private.photo_access(name,'progress_photos')));
-- No overwrite policy: unique upload paths prevent overwriting somebody else's file.
insert into public.profiles(id) select id from auth.users on conflict do nothing;
insert into public.preferences(owner_id) select id from auth.users on conflict do nothing;
revoke execute on all functions in schema private from public,anon;
grant execute on function private.conversation_access(uuid),private.feed_access(uuid),private.exchange_access(uuid),private.challenge_access(uuid),private.photo_access(text,text) to authenticated;
revoke execute on function public.send_workout_exchange(uuid,uuid,text),public.respond_workout_exchange(uuid,boolean),public.return_exchange_results(uuid,uuid),public.publish_workout(uuid),public.respond_relationship(uuid,boolean) from public,anon;
grant execute on function public.send_workout_exchange(uuid,uuid,text),public.respond_workout_exchange(uuid,boolean),public.return_exchange_results(uuid,uuid),public.publish_workout(uuid),public.respond_relationship(uuid,boolean) to authenticated;
commit;
